const Database = require('better-sqlite3');

try {
    const db = new Database('.tmp/data.db');

    // Known hash for '123123' generated by bcryptjs
    // $2b$10$FBbEwNzUIwgU9nOyoIp0t.MBDFa2tFTpK6ncgCzk0Rd85WolfrylW
    const newHash = '$2b$10$FBbEwNzUIwgU9nOyoIp0t.MBDFa2tFTpK6ncgCzk0Rd85WolfrylW';

    const stmt = db.prepare("UPDATE portal_admins SET password = ? WHERE email = ?");
    const info = stmt.run(newHash, 'q@q.com');

    console.log('Updated rows:', info.changes);

} catch (e) {
    console.error(e);
}
